    if let Some(cl) = headers.lines().find(|l| l.to_lowercase().starts_with("content-length:")) {
        if let Some(len_str) = cl.split(':').nth(1) {
            if let Ok(len) = len_str.trim().parse::<usize>() {
                return Ok(buf[headers_end..headers_end + len].to_vec());
            }
        }
    }

    // Fallback: return everything after headers
    Ok(buf[headers_end..].to_vec())
}

fn decode_chunked(data: &[u8]) -> Result<Vec<u8>> {
    let mut result = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        // Find chunk size line
        let mut line_end = pos;
        while line_end < data.len() && data[line_end] != b'\n' {
            line_end += 1;
        }
        if line_end >= data.len() { break; }
        let line = std::str::from_utf8(&data[pos..line_end]).unwrap_or("");
        let size = usize::from_str_radix(line.trim().split(';').next().unwrap_or("0").trim(), 16).unwrap_or(0);
        if size == 0 { break; }
        pos = line_end + 1;
        // Skip \r if present
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        // Copy chunk data
        result.extend_from_slice(&data[pos..pos + size]);
        pos += size;
        // Skip trailing \r\n
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        if pos < data.len() && data[pos] == b'\n' { pos += 1; }
    }
    Ok(result)
}
