```rust
use tokio::io::{AsyncReadExt, AsyncWriteExt};

async fn incus_api_request(method: &str, path: &str, body: Option<&str>) -> Result<Vec<u8>> {
    let socket_path = "/var/lib/incus/unix.socket";
    if !std::path::Path::new(socket_path).exists() {
        return Err(anyhow::anyhow!("Incus Unix socket not found at {}", socket_path));
    }

    let mut stream = tokio::net::UnixStream::connect(socket_path)
        .await
        .context("Failed to connect to Incus Unix socket")?;

    let body_len = body.map(|b| b.len()).unwrap_or(0);
    let request = format!(
        "{} {} HTTP/1.1\r\nHost: localhost\r\nAccept: application/json\r\n{}Content-Length: {}\r\n\r\n{}",
        method,
        path,
        if body.is_some() { "Content-Type: application/json\r\n" } else { "" },
        body_len,
        body.unwrap_or("")
    );

    stream.write_all(request.as_bytes()).await?;

    let mut response = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        let n = tokio::time::timeout(tokio::time::Duration::from_secs(5), stream.read(&mut buf))
            .await
            .context("Incus API request timed out")??;
        if n == 0 { break; }
        response.extend_from_slice(&buf[..n]);
        // Check if we have a complete response
        if response.windows(4).any(|w| w == b"\r\n\r\n") {
            // We have headers, check content-length or chunked
            let resp_str = String::from_utf8_lossy(&response);
            if let Some(headers_end) = resp_str.find("\r\n\r\n") {
                let headers = &resp_str[..headers_end];
                if headers.to_lowercase().contains("transfer-encoding: chunked") {
                    // Check if we have the final 0 chunk
                    let body = &resp_str[headers_end + 4..];
                    if body.contains("\r\n0\r\n") || body.contains("\n0\n") {
                        break;
                    }
                } else if let Some(cl_line) = headers.lines().find(|l| l.to_lowercase().starts_with("content-length:")) {
                    if let Some(len_str) = cl_line.split(':').nth(1) {
                        if let Ok(len) = len_str.trim().parse::<usize>() {
                            if response.len() >= headers_end + 4 + len {
                                break;
                            }
                        }
                    }
                } else {
                    // No content-length, assume complete if we got here
                    break;
                }
            }
        }
    }

    // Extract body
    let resp_str = String::from_utf8_lossy(&response);
    if let Some(idx) = resp_str.find("\r\n\r\n") {
        Ok(response[idx + 4..].to_vec())
    } else {
        Ok(response)
    }
}
```

