Actually, for Incus, the responses might use chunked encoding or content-length. Let me write a simple helper to extract the body:

```rust
fn extract_http_body(response: &[u8]) -> Result<Vec<u8>> {
    let resp_str = String::from_utf8_lossy(response);
    let headers_end = if let Some(idx) = resp_str.find("\r\n\r\n") {
        idx + 4
    } else if let Some(idx) = resp_str.find("\n\n") {
        idx + 2
    } else {
        return Ok(response.to_vec());
    };

    let headers = &resp_str[..headers_end];
    let body = &response[headers_end..];

    if headers.to_lowercase().contains("transfer-encoding: chunked") {
        let mut result = Vec::new();
        let mut pos = 0;
        while pos < body.len() {
            // Find chunk size line
            let mut line_end = pos;
            while line_end < body.len() && body[line_end] != b'\n' {
                line_end += 1;
            }
            if line_end >= body.len() { break; }
            let line = std::str::from_utf8(&body[pos..line_end]).unwrap_or("").trim();
            let size = usize::from_str_radix(line.split(';').next().unwrap_or("0").trim(), 16).unwrap_or(0);
            if size == 0 { break; }
            pos = line_end + 1;
            // Skip \r if present at start of chunk data
            if pos < body.len() && body[pos] == b'\r' { pos += 1; }
            result.extend_from_slice(&body[pos..pos + size]);
            pos += size;
            // Skip trailing \r\n
            if pos < body.len() && body[pos] == b'\r' { pos += 1; }
            if pos < body.len() && body[pos] == b'\n' { pos += 1; }
        }
        Ok(result)
    } else if let Some(cl_line) = headers.lines().find(|l| l.to_lowercase().starts_with("content-length:")) {
        if let Some(len_str) = cl_line.split(':').nth(1) {
            if let Ok(len) = len_str.trim().parse::<usize>() {
                return Ok(body[..len.min(body.len())].to_vec());
            }
        }
    }

    Ok(body.to_vec())
}
```

