async fn incus_api_request(method: &str, path: &str, body: Option<&str>) -> Result<Vec<u8>> {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::time::{timeout, Duration};

    let socket_path = "/var/lib/incus/unix.socket";
    if !std::path::Path::new(socket_path).exists() {
        return Err(anyhow::anyhow!("Incus Unix socket not found at {}", socket_path));
    }

    let mut stream = tokio::net::UnixStream::connect(socket_path)
        .await
        .context("Failed to connect to Incus Unix socket")?;

    let mut request = format!(
        "{} {} HTTP/1.1\r\nHost: localhost\r\nAccept: application/json\r\n",
        method, path
    );
    if let Some(b) = body {
        request.push_str(&format!("Content-Type: application/json\r\nContent-Length: {}\r\n", b.len()));
        request.push_str("\r\n");
        request.push_str(b);
    } else {
        request.push_str("\r\n");
    }

    stream.write_all(request.as_bytes()).await?;

    let mut buf = vec![0u8; 65536];
    let n = timeout(Duration::from_secs(5), stream.read(&mut buf))
        .await
        .context("Incus API request timed out")??;
    buf.truncate(n);

    // Parse Content-Length from headers to extract body
    let response = String::from_utf8_lossy(&buf);
    let mut headers_end = 0;
    if let Some(idx) = response.find("\r\n\r\n") {
        headers_end = idx + 4;
    } else if let Some(idx) = response.find("\n\n") {
        headers_end = idx + 2;
    }

    // Check for chunked encoding or content-length
    let headers = &response[..headers_end];
    if headers.to_lowercase().contains("transfer-encoding: chunked") {
        // Simple chunked decoder
        return Ok(decode_chunked(&buf[headers_end..])?);
    }

    if let Some(cl) = headers.lines().find(|l| l.to_lowercase().starts_with("content-length:")) {
        if let Some(len_str) = cl.split(':').nth(1) {
            if let Ok(len) = len_str.trim().parse::<usize>() {
                return Ok(buf[headers_end..headers_end + len].to_vec());
            }
        }
    }

    // Fallback: return everything after headers
    Ok(buf[headers_end..].to_vec())
}

fn decode_chunked(data: &[u8]) -> Result<Vec<u8>> {
    let mut result = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        // Find chunk size line
        let mut line_end = pos;
        while line_end < data.len() && data[line_end] != b'\n' {
            line_end += 1;
        }
        if line_end >= data.len() { break; }
        let line = std::str::from_utf8(&data[pos..line_end]).unwrap_or("");
        let size = usize::from_str_radix(line.trim().split(';').next().unwrap_or("0").trim(), 16).unwrap_or(0);
        if size == 0 { break; }
        pos = line_end + 1;
        // Skip \r if present
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        // Copy chunk data
        result.extend_from_slice(&data[pos..pos + size]);
        pos += size;
        // Skip trailing \r\n
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        if pos < data.len() && data[pos] == b'\n' { pos += 1; }
    }
    Ok(result)
}
```

